## File 5 of 12: `frontend/app/contract/[id]/ClauseSection.tsx`

This is the most complex new component. It handles two modes: **empty** (non-collapsible placeholder with celebratory/warning icon) and **populated** (collapsible header with count, expanding to reveal ClauseCards in a scroll-constrained container).

**PR excerpt:**

```typescript
// frontend/app/contract/[id]/ClauseSection.tsx
export default function ClauseSection({ rating, clauses }: ClauseSectionProps) {
  const [expanded, setExpanded] = useState(false);
  const { label } = getFairnessDisplay(rating);

  if (clauses.length === 0) {
    const isCelebratory = rating !== 'fair';
    const icon = isCelebratory ? '✓' : '⚠';
    const text = isCelebratory
      ? `No ${label.toLowerCase()} clauses`
      : 'No fair clauses found';
    return (
      <div className="flex items-center gap-2 rounded-lg border border-foreground/10 px-4 py-3 text-foreground/50">
        <span>{icon}</span>
        <span>{text}</span>
      </div>
    );
  }

  return (
    <div>
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="flex w-full items-center justify-between rounded-lg border border-foreground/10 px-4 py-3 text-left hover:bg-foreground/5"
      >
        <span className="font-semibold">{label} ({clauses.length})</span>
        <span className="text-foreground/40">{expanded ? '−' : '+'}</span>
      </button>
      {expanded && (
        <div className="mt-2 max-h-[50vh] space-y-2 overflow-y-auto">
          {clauses.map((clause, index) => (
            <ClauseCard key={`${clause.section_number}-${index}`} clause={clause} />
          ))}
        </div>
      )}
    </div>
  );
}
```

Walk through: what are the two render paths, how does the empty-state icon logic work, and why is the key a compound of `section_number` and `index`? Restate in your own words.

